SELECT n.id, n.title, n.view_count, n.download_count, n.favorite_count, n.updated_at, c.id AS course_id, c.name AS course_name, n.uploader_id AS uploader_id FROM note n JOIN course c ON c.id = n.course_id
JOIN note_tag nt ON nt.note_id = n.id AND nt.tag_id = #{tagId}
WHERE n.status = #{status}
AND n.course_id = #{courseId}
AND n.title LIKE CONCAT('%', #{keyword}, '%') ESCAPE '/'
ORDER BY n.view_count DESC, n.id DESC
ORDER BY n.download_count DESC, n.id DESC
ORDER BY n.updated_at DESC, n.id DESC

SELECT n.id, n.title, n.view_count, n.download_count, n.favorite_count, n.created_at, n.updated_at, c.id AS course_id, c.name AS course_name, n.uploader_id AS uploader_id FROM note n JOIN course c ON c.id = n.course_id WHERE n.status = #{status}
AND n.title LIKE CONCAT('%', #{keyword}, '%') ESCAPE '/'
ORDER BY n.updated_at DESC, n.id DESC

SELECT nt.note_id, t.id AS tag_id, t.name AS tag_name FROM note_tag nt JOIN tag t ON t.id = nt.tag_id WHERE nt.note_id IN
#{noteId}
ORDER BY nt.note_id, t.id

